            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 0 and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            regions.append(cells)
    out = [row[:] for row in grid]
    if regions:
        sizes = [len(cells) for cells in regions]
        small, large = min(sizes), max(sizes)
        for cells, size in zip(regions, sizes):
            color = 7 if size == small else 8 if size == large else None
            if color is not None:
                for r, c in cells:
                    out[r][c] = color
